import { Cell, key } from './grid';

interface Neighbor fn...

export function astar(width, height, blocked: (x,y)=>boolean, start: Cell, goal: Cell): Cell[] | null {
  const manhattan = (a,b) => Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
  const sk = key(start);
  const gScore = new Map<string, number>([[sk, 0]]);
  const cameFrom = new Map<string, string>();
  const openSet: {k:string;c:Cell;f:number}[] = [{k:sk,c:start,f:manhattan(start,goal)}];
  const closed = new Set<string>();
  while (openSet.length) {
    let bi = 0;
    for (let i=1;i<openSet.length;i++) if (openSet[i].f < openSet[bi].f) bi=i;
    const cur = openSet.splice(bi,1)[0];
    if (closed.has(cur.k)) continue;
    closed.add(cur.k);
    if (cur.c.x===goal.x && cur.c.y===goal.y) {
      // reconstruct
      const path=[cur.c]; let k=cur.k;
      while (cameFrom.has(k)) { k=cameFrom.get(k)!; const [x,y]=k.split(',').map(Number); path.unshift({x,y}); }
      return path;
    }
    const dirs=[[1,0],[-1,0],[0,1],[0,-1]];
    for (const [dx,dy] of dirs) {
      const nx=cur.c.x+dx, ny=cur.c.y+dy;
      if (nx<0||ny<0||nx>=width||ny>=height) continue;
      if (blocked(nx,ny)) continue;
      const nk=key({x:nx,y:ny});
      if (closed.has(nk)) continue;
      const tg=gScore.get(cur.k)!+1;
      if (tg < (gScore.get(nk) ?? Infinity)) {
        gScore.set(nk,tg); cameFrom.set(nk,cur.k);
        openSet.push({k:nk,c:{x:nx,y:ny},f:tg+manhattan({x:nx,y:ny},goal)});
      }
    }
  }
  return null;
}
