export interface Cell {
  x: number;
  y: number;
}

export const key = (c: Cell): string => `${c.x},${c.y}`;

export const parseKey = (k: string): Cell => {
  const [x, y] = k.split(",").map(Number);
  return { x, y };
};

export const sameCell = (a: Cell, b: Cell): boolean =>
  a.x === b.x && a.y === b.y;

export const manhattan = (a: Cell, b: Cell): number =>
  Math.abs(a.x - b.x) + Math.abs(a.y - b.y);

/**
 * A time-aware wall set: every wall has a tick from which it exists.
 * `blockedAt` answers whether a cell is a wall *at a given tick*, so path
 * validity is always checked against the world as it exists at that moment.
 */
export class TimedWalls {
  /** key -> tick from which this cell is walled */
  private readonly from = new Map<string, number>();

  insert(c: Cell, atTick: number): void {
    const k = key(c);
    const existing = this.from.get(k);
    if (existing === undefined || atTick < existing) {
      this.from.set(k, atTick);
    }
  }

  blockedAt(c: Cell, tick: number): boolean {
    const t = this.from.get(key(c));
    return t !== undefined && tick >= t;
  }

  entries(): Array<{ cell: Cell; fromTick: number }> {
    return [...this.from.entries()].map(([k, fromTick]) => ({
      cell: parseKey(k),
      fromTick,
    }));
  }
}
