interface OpenNode {
  k: string;
  c: Cell;
  f: number;
}

const DIRS = [
  [1, 0],
  [-1, 0],
  [0, 1],
  [0, -1],
] as const;

/**
 * A* on a 4-connected unit-cost grid.
 *
 * @param width   grid width
 * @param height  grid height
 * @param blocked predicate telling whether a cell is currently a wall
 * @param start   start cell (assumed traversable)
 * @param goal    goal cell (assumed traversable)
 * @returns the full path including `start` and `goal`, or null if unreachable
 */
export function astar(
  width: number,
  height: number,
  blocked: (x: number, y: number) => boolean,
  start: Cell,
  goal: Cell,
): Cell[] | null {
  const sk = key(start);
  const gScore = new Map<string, number>([[sk, 0]]);
  const cameFrom = new Map<string, string>();
  const closed = new Set<string>();
  const open: OpenNode[] = [{ k: sk, c: start, f: manhattan(start, goal) }];

  while (open.length > 0) {
    // pop lowest-f node (grid is tiny; linear scan is fine)
    let best = 0;
    for (let i = 1; i < open.length; i++) {
      if (open[i].f < open[best].f) best = i;
    }
    const cur = open.splice(best, 1)[0];
    if (closed.has(cur.k)) continue;
    closed.add(cur.k);

    if (cur.c.x === goal.x && cur.c.y === goal.y) {
      // reconstruct path
      const path: Cell[] = [cur.c];
      let k = cur.k;
      while (cameFrom.has(k)) {
        k = cameFrom.get(k)!;
        const [x, y] = k.split(",").map(Number);
        path.unshift({ x, y });
      }
      return path;
    }

    for (const [dx, dy] of DIRS) {
      const nx = cur.c.x + dx;
      const ny = cur.c.y + dy;
      if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
      if (blocked(nx, ny)) continue;
      const nk = key({ x: nx, y: ny });
      if (closed.has(nk)) continue;

      const tentativeG = gScore.get(cur.k)! + 1;
      if (tentativeG < (gScore.get(nk) ?? Infinity)) {
        gScore.set(nk, tentativeG);
        cameFrom.set(nk, cur.k);
        const nextCell = { x: nx, y: ny };
        open.push({
          k: nk,
          c: nextCell,
          f: tentativeG + manhattan(nextCell, goal),
        });
      }
    }
  }
  return null;
}

/** Number of moves in an optimal 4-connected path (Manhattan distance). */
export const optimalMoves = (a: Cell, b: Cell): number => manhattan(a, b);
