import { type Cell, TimedWalls, key, sameCell } from "./grid";

export const WIDTH = 15;
export const HEIGHT = 15;
export const START: Cell = { x: 0, y: 0 };
export const GOAL: Cell = { x: 14, y: 14 };
/** After this many executed moves, the wall appears. */
export const WALL_AFTER_MOVES = 5;
/** How many upcoming cells of the remaining path the wall covers. */
export const WALL_LENGTH = 3;

export type EventType = "initial_plan" | "move" | "wall_inserted" | "replan" | "goal";

export interface SimEvent {
  tick: number; // tick at which the event happened (moves completed so far)
  type: EventType;
  /** for move events */
  to?: Cell;
  /** for wall_inserted events */
  cells?: Cell[];
  /** for plan/replan events */
  path?: Cell[];
}

export interface SimulationResult {
  /** every cell the agent occupied, starting at START */
  executedPath: Cell[];
  /** number of moves executed (= executedPath.length - 1) */
  executedMoves: number;
  walls: TimedWalls;
  events: SimEvent[];
  /** wall cells that were inserted mid-route, if any */
  insertedWall: Cell[] | null;
  originalPlan: Cell[];
  optimalMovesCount: number;
}

/**
 * Runs the dynamic-replanning scenario:
 *
 * 1. Plan an A* route on the empty 15x15 grid.
 * 2. Execute it step by step (one move per tick).
 * 3. After 5 executed moves, a wall segment covering the next 3 cells of the
 *    remaining path appears (it exists from that tick onward).
 * 4. Replan from the current position and continue until the goal is reached.
 *
 * Every planned/attempted step is validated against the walls as they exist
 * at that tick — the agent never steps into a live wall.
 */
export function runSimulation(): SimulationResult {
  const walls = new TimedWalls();
  const events: SimEvent[] = [];
  const executedPath: Cell[] = [{ ...START }];

  let tick = 0; // moves completed so far
  let insertedWall: Cell[] | null = null;
  let replanned = false;

  const blockedAtCurrentTick = (x: number, y: number): boolean =>
    x < 0 || y < 0 || x >= WIDTH || y >= HEIGHT || walls.blockedAt({ x, y }, tick);

  // ---- 1. initial plan on the open grid -----------------------------------
  const originalPlan = astar(WIDTH, HEIGHT, blockedAtCurrentTick, START, GOAL);
  if (!originalPlan) throw new Error("no path on the initially open grid");
  events.push({ tick, type: "initial_plan", path: originalPlan });

  // invariant: path[0] is always the agent's current position
  let path: Cell[] = originalPlan.map((c) => ({ ...c }));
  let pos = { ...START };

  while (!sameCell(pos, GOAL)) {
    // ---- 2. after 5 executed moves, drop a wall over the next 3 path cells
    if (
      tick === WALL_AFTER_MOVES &&
      !replanned &&
      path.length > 1
    ) {
      const ahead = path.slice(1, 1 + WALL_LENGTH);
      insertedWall = ahead;
      // The wall exists from this tick on — i.e., before the agent's next move.
      for (const c of ahead) walls.insert(c, tick);
      events.push({ tick, type: "wall_inserted", cells: ahead });

      // ---- 3. replan from the current position against the updated world
      const newPath = astar(WIDTH, HEIGHT, blockedAtCurrentTick, pos, GOAL);
      if (!newPath) throw new Error("replan failed: goal unreachable");
      path = newPath;
      replanned = true;
      events.push({ tick, type: "replan", path });
    }

    // ---- 4. take one step along the current plan --------------------------
    const next = path[1];
    // safety check: never enter a cell that is a wall at the tick we enter it
    if (walls.blockedAt(next, tick)) {
      throw new Error(
        `attempting to enter walled cell (${next.x},${next.y}) at tick ${tick}`,
      );
    }

    tick += 1;
    pos = { ...next };
    executedPath.push(pos);
    path.shift();
    events.push({ tick, type: "move", to: pos });

    // if somehow the current plan runs into the new wall later, replanning
    // here would be needed too — but in this scenario the single replan above
    // already accounts for all walls, so `path` stays valid.
  }

  events.push({ tick, type: "goal" });

  return {
    executedPath,
    executedMoves: tick,
    walls,
    events,
    insertedWall,
    originalPlan,
    optimalMovesCount: optimalMoves(START, GOAL),
  };
}

/** Convenience helper used by tests: replay a path against timed walls. */
export function validateAgainstWalls(path: Cell[], walls: TimedWalls): void {
  for (let t = 1; t < path.length; t++) {
    const c = path[t];
    if (walls.blockedAt(c, t - 1)) {
      throw new Error(`cell ${key(c)} entered at tick ${t - 1} while walled`);
    }
  }
}
